1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body { margin: 0; font: 16px/1.4 system-ui, sans-serif; background: #f6f6f4; color: #222; }
10	  main { max-width: 520px; margin: 40px auto; padding: 0 16px; }
11	  h1 { font-size: 1.6rem; margin: 0 0 16px; }
12	  form { display: flex; gap: 8px; margin-bottom: 16px; }
13	  input { flex: 1; padding: 10px; font: inherit; border: 1px solid #ccc; border-radius: 6px; }
14	  button { padding: 10px 14px; font: inherit; border: 0; border-radius: 6px; background: #2b6cb0; color: #fff; cursor: pointer; }
15	  ul { list-style: none; margin: 0; padding: 0; }
16	  li { display: flex; align-items: center; gap: 8px; padding: 10px 12px; background: #fff; border: 1px solid #e3e3e3; border-radius: 6px; margin-bottom: 8px; }
17	  li span { flex: 1; word-break: break-word; }
18	  li button { background: #c53030; padding: 6px 10px; font-size: 0.9rem; }
19	  li input[type="checkbox"] { flex: none; width: 18px; height: 18px; margin: 0; }
20	  li[data-completed="true"] span { text-decoration: line-through; color: #888; }
21	  input[type="date"] { flex: none; }
22	  li .due { flex: none; font-size: 0.85rem; color: #555; }
23	  select { flex: none; padding: 10px; font: inherit; border: 1px solid #ccc; border-radius: 6px; background: #fff; }
24	  li .priority { flex: none; font-size: 0.85rem; color: #555; }
25	  li[data-overdue="true"] { border-color: #c53030; background: #fff5f5; }
26	  li[data-overdue="true"] .due { color: #c53030; font-weight: 600; }
27	  .search { display: block; width: 100%; margin-bottom: 16px; }
28	  li .edit { padding: 4px 8px; }
29	  .filters { display: flex; gap: 8px; margin-bottom: 16px; }
30	  .filters button { background: #e2e8f0; color: #222; padding: 6px 12px; font-size: 0.9rem; }
31	  .filters button[aria-pressed="true"] { background: #2b6cb0; color: #fff; }
32	</style>
33	</head>
34	<body>
35	<main>
36	  <h1>Todos</h1>
37	  <form id="todo-form">
38	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" autocomplete="off" aria-label="New todo">
39	    <input data-testid="todo-due" type="date" aria-label="Due date">
40	    <select data-testid="todo-priority" aria-label="Priority">
41	      <option value="low">Low</option>
42	      <option value="med" selected>Med</option>
43	      <option value="high">High</option>
44	    </select>
45	    <button data-testid="todo-add" type="submit">Add</button>
46	  </form>
47	  <input class="search" data-testid="search-input" type="search" placeholder="Search todos" autocomplete="off" aria-label="Search todos">
48	  <div class="filters">
49	    <button data-testid="filter-all" data-filter="all" type="button" aria-pressed="true">All</button>
50	    <button data-testid="filter-active" data-filter="active" type="button" aria-pressed="false">Active</button>
51	    <button data-testid="filter-completed" data-filter="completed" type="button" aria-pressed="false">Completed</button>
52	  </div>
53	  <ul data-testid="todo-list"></ul>
54	</main>
55	<script>
56	  var STORAGE_KEY = 'todos';
57	  var form = document.getElementById('todo-form');
58	  var input = document.querySelector('[data-testid="todo-input"]');
59	  var dueInput = document.querySelector('[data-testid="todo-due"]');
60	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
61	  var list = document.querySelector('[data-testid="todo-list"]');
62	  var filterButtons = document.querySelectorAll('[data-filter]');
63	  var searchInput = document.querySelector('[data-testid="search-input"]');
64	  var todos = loadTodos();
65	  var currentFilter = 'all';
66	  var searchTerm = '';
67	
68	  // [REQ-001]
69	  function loadTodos() {
70	    try {
71	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
72	      return Array.isArray(data) ? data : [];
73	    } catch (e) {
74	      return [];
75	    }
76	  }
77	
78	  // [REQ-001]
79	  function saveTodos() {
80	    try {
81	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
82	    } catch (e) {}
83	  }
84	
85	  // [REQ-001]
86	  function makeId() {
87	    if (window.crypto && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
88	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
89	  }
90	
91	  // [REQ-003] Due dates are plain local YYYY-MM-DD strings; never parsed through UTC.
92	  function normalizeDue(value) {
93	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : null;
94	  }
95	
96	  // [REQ-003] Today's LOCAL calendar date as YYYY-MM-DD.
97	  function localToday(now) {
98	    now = now || new Date();
99	    var m = String(now.getMonth() + 1).padStart(2, '0');
100	    var d = String(now.getDate()).padStart(2, '0');
101	    return now.getFullYear() + '-' + m + '-' + d;
102	  }
103	
104	  // [REQ-003] Overdue = due date strictly before today's local date (date-only string compare).
105	  function isOverdue(due, today) {
106	    return !!due && due < today;
107	  }
108	
109	  // [REQ-004] Priority is low, med or high; anything else (including missing) is med.
110	  function normalizePriority(value) {
111	    return value === 'low' || value === 'high' ? value : 'med';
112	  }
113	
114	  // [REQ-001] [REQ-003] [REQ-004]
115	  function addTodo(text, due, priority) {
116	    text = text.trim();
117	    if (!text) return;
118	    todos.push({ id: makeId(), text: text, createdAt: Date.now(), completed: false, due: normalizeDue(due), priority: normalizePriority(priority) });
119	    saveTodos();
120	    render();
121	  }
122	
123	  // [REQ-001]
124	  function deleteTodo(id) {
125	    todos = todos.filter(function (t) { return t.id !== id; });
126	    saveTodos();
127	    render();
128	  }
129	
130	  // [REQ-002]
131	  function toggleTodo(id) {
132	    todos.forEach(function (t) {
133	      if (t.id === id) t.completed = !t.completed;
134	    });
135	    saveTodos();
136	    render();
137	  }
138	
139	  // [REQ-005] Highest priority first; insertion order within the same priority. Does not mutate items.
140	  function byPriority(items) {
141	    var rank = { high: 0, med: 1, low: 2 };
142	    return items
143	      .map(function (t, i) { return { t: t, i: i }; })
144	      .sort(function (a, b) {
145	        return (rank[normalizePriority(a.t.priority)] - rank[normalizePriority(b.t.priority)]) || (a.i - b.i);
146	      })
147	      .map(function (x) { return x.t; });
148	  }
149	
150	  // [REQ-007] Case-insensitive substring match; an empty term matches everything.
151	  function matchesSearch(text, term) {
152	    return String(text).toLowerCase().indexOf(String(term || '').toLowerCase()) !== -1;
153	  }
154	
155	  // [REQ-007] Replace a todo's text. Blank text keeps the old text.
156	  function editTodo(id, text) {
157	    text = String(text).trim();
158	    if (!text) return render();
159	    todos.forEach(function (t) {
160	      if (t.id === id) t.text = text;
161	    });
162	    saveTodos();
163	    render();
164	  }
165	
166	  // [REQ-002] [REQ-005] [REQ-007] Search narrows the list; then active first, completed below, by priority and insertion order.
167	  function visibleTodos(items, filter, term) {
168	    items = items.filter(function (t) { return matchesSearch(t.text, term); });
169	    var active = byPriority(items.filter(function (t) { return !t.completed; }));
170	    var done = byPriority(items.filter(function (t) { return !!t.completed; }));
171	    if (filter === 'active') return active;
172	    if (filter === 'completed') return done;
173	    return active.concat(done);
174	  }
175	
176	  // [REQ-002]
177	  function setFilter(filter) {
178	    currentFilter = filter;
179	    render();
180	  }
181	
182	  // [REQ-001] [REQ-002] [REQ-003] [REQ-004] [REQ-006] Priority shown as plain text, no colour coding.
183	  function render() {
184	    var today = localToday();
185	    list.textContent = '';
186	    filterButtons.forEach(function (btn) {
187	      btn.setAttribute('aria-pressed', String(btn.dataset.filter === currentFilter));
188	    });
189	    visibleTodos(todos, currentFilter, searchTerm).forEach(function (todo) {
190	      var li = document.createElement('li');
191	      li.setAttribute('data-testid', 'todo-item');
192	      li.setAttribute('data-completed', String(!!todo.completed));
193	      li.setAttribute('data-overdue', String(isOverdue(normalizeDue(todo.due), today)));
194	      li.setAttribute('data-priority', normalizePriority(todo.priority));
195	      li.dataset.id = todo.id;
196	
197	      var toggle = document.createElement('input');
198	      toggle.type = 'checkbox';
199	      toggle.setAttribute('data-testid', 'todo-toggle');
200	      toggle.setAttribute('aria-label', 'Mark complete');
201	      toggle.checked = !!todo.completed;
202	      toggle.addEventListener('change', function () { toggleTodo(todo.id); });
203	
204	      var span = document.createElement('span');
205	      span.setAttribute('data-testid', 'todo-text');
206	      span.textContent = todo.text;
207	      span.addEventListener('dblclick', function () { startEdit(span, todo); });
208	
209	      var del = document.createElement('button');
210	      del.type = 'button';
211	      del.setAttribute('data-testid', 'todo-delete');
212	      del.textContent = 'Delete';
213	      del.addEventListener('click', function () { deleteTodo(todo.id); });
214	
215	      li.appendChild(toggle);
216	      li.appendChild(span);
217	      var priority = document.createElement('span');
218	      priority.className = 'priority';
219	      priority.textContent = { high: 'High', med: 'Med', low: 'Low' }[normalizePriority(todo.priority)];
220	      li.appendChild(priority);
221	      if (normalizeDue(todo.due)) {
222	        var due = document.createElement('span');
223	        due.className = 'due';
224	        due.setAttribute('data-testid', 'todo-due-label');
225	        due.textContent = 'Due ' + todo.due;
226	        li.appendChild(due);
227	      }
228	      li.appendChild(del);
229	      list.appendChild(li);
230	    });
231	  }
232	
233	  // [REQ-007] Double-click turns the text into a field. Enter or blur commits; Escape cancels.
234	  function startEdit(span, todo) {
235	    var field = document.createElement('input');
236	    field.type = 'text';
237	    field.className = 'edit';
238	    field.setAttribute('data-testid', 'todo-edit');
239	    field.setAttribute('aria-label', 'Edit todo');
240	    field.value = todo.text;
241	    var finished = false;
242	    function finish(commit) {
243	      if (finished) return;
244	      finished = true;
245	      if (commit) editTodo(todo.id, field.value);
246	      else render();
247	    }
248	    field.addEventListener('keydown', function (e) {
249	      if (e.key === 'Enter') { e.preventDefault(); finish(true); }
250	      else if (e.key === 'Escape') { e.preventDefault(); finish(false); }
251	    });
252	    field.addEventListener('blur', function () { finish(true); });
253	    span.replaceWith(field);
254	    field.focus();
255	    field.select();
256	  }
257	
258	  // [REQ-007]
259	  searchInput.addEventListener('input', function () {
260	    searchTerm = searchInput.value;
261	    render();
262	  });
263	
264	  filterButtons.forEach(function (btn) {
265	    btn.addEventListener('click', function () { setFilter(btn.dataset.filter); });
266	  });
267	
268	  form.addEventListener('submit', function (e) {
269	    e.preventDefault();
270	    addTodo(input.value, dueInput.value, priorityInput.value);
271	    input.value = '';
272	    dueInput.value = '';
273	    priorityInput.value = 'med';
274	    input.focus();
275	  });
276	
277	  render();
278	</script>
279	</body>
280	</html>
281

